@Override
    public void onUseTick(Level level, LivingEntity livingEntity, ItemStack stack, int remainingUseDuration) {
        if (!(livingEntity instanceof Player player))
            return;

        if (player.isPassenger())
            player.stopRiding();

        if (level.isClientSide())
            return;

        var path = new ArrayList<>(stack.getOrDefault(RelicsDataComponents.CLOT_OF_TIME_PATH, List.<PathPointData>of()));

        if (path.size() < 2) {
            stack.set(RelicsDataComponents.CLOT_OF_TIME_REWIND_CURSOR, -1D);

            if (this.getCooldown(stack) <= 0)
                this.setCooldown(stack, Math.max(1, player.getTicksUsingItem()));

            player.stopUsingItem();

            return;
        }

        var lastIndex = path.size() - 1;
        var cursor = (double) stack.getOrDefault(RelicsDataComponents.CLOT_OF_TIME_REWIND_CURSOR, -1D);

        if (cursor < 0D || cursor > lastIndex)
            cursor = lastIndex;

        var speed = 1.05D + Math.min(3D, Math.max(0, player.getTicksUsingItem() - 1) * 0.01D);

        cursor = Math.max(0D, cursor - speed);

        var segment = Mth.floor(cursor);

        var t = (float) (cursor - segment);

        var p1 = path.get(segment);
        var p2 = path.get(Math.min(lastIndex, segment + 1));

        if (player instanceof ServerPlayer serverPlayer) {
            var p0 = path.get(Math.max(0, segment - 1));
            var p3 = path.get(Math.min(lastIndex, segment + 2));
            var currentDimension = serverPlayer.level().dimension().location().toString();
            var p1Dimension = p1.dimension().isBlank() ? currentDimension : p1.dimension();
            var p2Dimension = p2.dimension().isBlank() ? currentDimension : p2.dimension();

            if (!p1Dimension.equals(currentDimension)) {
                var dimensionId = ResourceLocation.tryParse(p1Dimension);

                if (dimensionId != null) {
                    var key = ResourceKey.create(Registries.DIMENSION, dimensionId);
                    var targetLevel = serverPlayer.server.getLevel(key);

                    if (targetLevel != null) {
                        serverPlayer.teleportTo(targetLevel, p1.x(), p1.y(), p1.z(), p1.yRot(), p1.xRot());
                        serverPlayer.setPortalCooldown();
                        serverPlayer.setDeltaMovement(Vec3.ZERO);
                        serverPlayer.fallDistance = 0F;

                        setRewindCursor(stack, -1D);
                        setPath(stack, path);

                        player.stopUsingItem();

                        return;
                    }
                }
            }

            double targetX;
            double targetY;
            double targetZ;

            float targetYRot;
            float targetXRot;

            if (!p1Dimension.equals(p2Dimension)) {
                var point = p1Dimension.equals(currentDimension) ? p1 : p2;

                targetX = point.x();
                targetY = point.y();
                targetZ = point.z();

                targetYRot = point.yRot();
                targetXRot = point.xRot();
            } else {
                targetX = Mth.catmullrom(t, (float) p0.x(), (float) p1.x(), (float) p2.x(), (float) p3.x());
                targetY = Mth.catmullrom(t, (float) p0.y(), (float) p1.y(), (float) p2.y(), (float) p3.y());
                targetZ = Mth.catmullrom(t, (float) p0.z(), (float) p1.z(), (float) p2.z(), (float) p3.z());

                var targetRotation = this.interpolateLookRotationCatmullrom(t, p0, p1, p2, p3);

                targetYRot = targetRotation.yRot();
                targetXRot = targetRotation.xRot();
            }

            var clampedXRot = Mth.clamp(targetXRot, -90F, 90F);

            if (serverPlayer.distanceToSqr(targetX, targetY, targetZ) > 16D * 16D)
                serverPlayer.teleportTo((ServerLevel) serverPlayer.level(), targetX, targetY, targetZ, targetYRot, clampedXRot);
            else
                serverPlayer.moveTo(targetX, targetY, targetZ, targetYRot, clampedXRot);

            serverPlayer.setYHeadRot(targetYRot);
            serverPlayer.yHeadRotO = targetYRot;
            serverPlayer.yBodyRot = targetYRot;
            serverPlayer.yBodyRotO = targetYRot;
            serverPlayer.setDeltaMovement(Vec3.ZERO);
            serverPlayer.fallDistance = 0F;
        }

        if (level instanceof ServerLevel) {
            var random = level.random;
            var previousCenter = new Vec3(player.xOld, player.yOld + player.getBbHeight() * 0.55D, player.zOld);
            var currentCenter = new Vec3(player.getX(), player.getY() + player.getBbHeight() * 0.55D, player.getZ());
            var movement = currentCenter.subtract(previousCenter);
            var distance = movement.length();
            var spawnCount = Mth.clamp((int) Math.ceil(distance / 0.125D), 2, 5);
            var phase = player.tickCount * 0.45D;

            for (int step = 0; step <= spawnCount; step++) {
                var progress = spawnCount == 0 ? 0D : (double) step / spawnCount;
                var center = previousCenter.add(movement.scale(progress));
                var subPhase = phase + progress * 0.35D;

                for (int i = 0; i < 6; i++) {
                    var angle = subPhase + i * (Math.PI * 2D / 6D);
                    var radius = 0.45D + 0.12D * Math.sin(subPhase * 1.6D + i);

                    var px = center.x + Math.cos(angle) * radius;
                    var pz = center.z + Math.sin(angle) * radius;
                    var py = center.y + Math.sin(angle * 1.7D) * 0.2D;

                    var hue = (float) ((0.58D + subPhase * 0.025D + i * 0.06D) % 1D);
                    var color = Color.getHSBColor(hue, 0.6F + random.nextFloat() * 0.25F, 1F);

                    var inward = new Vec3(center.x - px, center.y - py, center.z - pz).scale(0.1D);
                    var swirl = new Vec3(-Math.sin(angle), 0D, Math.cos(angle)).scale(0.03D);

                    var velocity = inward.add(swirl).add(0D, 0.01D + random.nextDouble() * 0.01D, 0D);

                    NetworkHandler.sendToClientsTrackingEntityAndSelf(new S2CSpawnParticle(ParticleUtils.constructSimpleSpark(color, 0.25F + random.nextFloat() * 0.15F, 20 + random.nextInt(10), 0.975F), new Vector3f((float) px, (float) py, (float) pz),
                            new Vector3f((float) velocity.x, (float) velocity.y, (float) velocity.z)), player);
                }
            }
        }

        var ability = this.getRelicData(player, stack).getAbilitiesData().getAbilityData("rewind");

        if (ability.canPlayerUse(player)) {
            this.getRelicData(player, stack).getLevelingData().addExperience("rewind", "rewind", 1D / 20D);

            ability.getStatisticData().getMetricData("rewind_duration").addValue(1D / 20D);
        }

        if (ability.canPlayerUse(player) && ability.getRankModifierData("health_rewind").isEnabled()) {
            var rewindHealth = Mth.lerp(t, p1.health(), p2.health());
            var currentHealth = player.getHealth();
            var targetHealth = Math.min(player.getMaxHealth(), Math.max(currentHealth, rewindHealth));

            if (targetHealth > currentHealth) {
                player.setHealth(targetHealth);

                if (ability.canPlayerUse(player) && ability.getRankModifierData("health_rewind").isEnabled()) {
                    this.getRelicData(player, stack).getLevelingData().addExperience("rewind", "health_rewind", targetHealth - currentHealth);
                    ability.getStatisticData().getMetricData("health_restored").addValue(targetHealth - currentHealth);
                }
            }
        }

        while (path.size() > 2 && cursor <= path.size() - 2)
            path.removeLast();

        if (cursor <= 0D) {
            setRewindCursor(stack, -1D);
            setPath(stack, path);

            if (this.getCooldown(stack) <= 0)
                this.setCooldown(stack, Math.max(1, player.getTicksUsingItem()));

            player.stopUsingItem();

            return;
        }

        setRewindCursor(stack, cursor);
        setPath(stack, path);
    }

@Override
    public InteractionResultHolder<ItemStack> use(Level level, Player player, InteractionHand hand) {
        var stack = player.getItemInHand(hand);

        if (this.getRememberedTicks(player, stack) <= 0 || stack.getOrDefault(RelicsDataComponents.CLOT_OF_TIME_PATH, List.<PathPointData>of()).size() < 2 || this.getCooldown(stack) > 0)
            return InteractionResultHolder.pass(stack);

        if (!level.isClientSide()) {
            setRewindCursor(stack, -1D);

            this.setCooldown(stack, 0);

            var ability = this.getRelicData(player, stack).getAbilitiesData().getAbilityData("rewind");

            if (ability.canPlayerUse(player))
                ability.getStatisticData().getMetricData("activations").addValue(1D);
        }

        player.startUsingItem(hand);

        return InteractionResultHolder.consume(stack);
    }

@SubscribeEvent
        public static void onEntityTick(EntityTickEvent.Post event) {
            if (!(event.getEntity() instanceof ServerPlayer player) || player.level().isClientSide())
                return;

            var usingSlot = -1;
            var currentDimension = player.level().dimension().location().toString();

            if (player.isUsingItem() && player.getUseItem().getItem() instanceof ClotOfTimeItem)
                usingSlot = player.getUsedItemHand() == InteractionHand.MAIN_HAND ? player.getInventory().selected : Inventory.SLOT_OFFHAND;

            PathPointData pointToAppend = null;

            for (int i = 0; i < player.getInventory().getContainerSize(); i++) {
                var stack = player.getInventory().getItem(i);

                if (!(stack.getItem() instanceof ClotOfTimeItem relic))
                    continue;

                var rememberedTicks = relic.getRememberedTicks(player, stack);

                if (rememberedTicks <= 0) {
                    setPath(stack, List.of());
                    setRewindCursor(stack, -1D);
                    relic.setCooldown(stack, 0);

                    continue;
                }

                var cursor = stack.getOrDefault(RelicsDataComponents.CLOT_OF_TIME_REWIND_CURSOR, -1D);
                var storedPath = stack.getOrDefault(RelicsDataComponents.CLOT_OF_TIME_PATH, List.<PathPointData>of());
                var usingThisStack = i == usingSlot;
                var justStoppedRewind = false;

                if (usingThisStack) {
                    var ability = relic.getRelicData(player, stack).getAbilitiesData().getAbilityData("rewind");

                    if (ability.canPlayerUse(player) && ability.getRankModifierData("oblivion").isEnabled()) {
                        for (var mob : player.level().getEntitiesOfClass(Mob.class, player.getBoundingBox().inflate(16D))) {
                            if (mob.getTarget() == player)
                                mob.setTarget(null);
                        }
                    }
                }

                if (usingThisStack && cursor >= 0D)
                    relic.setCooldown(stack, Math.max(relic.getCooldown(stack), Math.max(1, player.getTicksUsingItem())));

                if (!usingThisStack && cursor >= 0D) {
                    setRewindCursor(stack, -1D);

                    if (!storedPath.isEmpty()) {
                        var lastPoint = storedPath.getLast();
                        var lastDimension = lastPoint.dimension().isBlank() ? currentDimension : lastPoint.dimension();

                        if (!lastDimension.equals(currentDimension))
                            relic.setCooldown(stack, 0);
                        else if (relic.getCooldown(stack) <= 0)
                            relic.setCooldown(stack, 1);
                    } else if (relic.getCooldown(stack) <= 0)
                        relic.setCooldown(stack, 1);

                    justStoppedRewind = true;
                }

                if (usingThisStack)
                    continue;

                if (!justStoppedRewind) {
                    var cooldown = relic.getCooldown(stack);

                    if (cooldown > 0)
                        relic.setCooldown(stack, cooldown - 1);
                }

                if (!storedPath.isEmpty() && !shouldAppendPoint(player, storedPath.getLast(), currentDimension))
                    continue;

                if (pointToAppend == null)
                    pointToAppend = PathPointData.fromPlayer(player, currentDimension);

                setPath(stack, buildUpdatedPath(storedPath, rememberedTicks, pointToAppend));
            }
        }

@SubscribeEvent
        public static void onLivingDamage(LivingIncomingDamageEvent event) {
            if (!(event.getEntity() instanceof Player player) || player.level().isClientSide())
                return;

            if (!(player.isUsingItem() && player.getUseItem().getItem() instanceof ClotOfTimeItem relic))
                return;

            var ability = relic.getRelicData(player, player.getUseItem()).getAbilitiesData().getAbilityData("rewind");

            if (!ability.canPlayerUse(player) || !ability.getRankModifierData("invulnerability").isEnabled())
                return;

            event.setCanceled(true);
        }

private int getRememberedTicks(Player player, ItemStack stack) {
        var ability = this.getRelicData(player, stack).getAbilitiesData().getAbilityData("rewind");

        if (!ability.canPlayerUse(player))
            return 0;

        return Math.max(1, (int) Math.round(ability.getStatData("time").getValue() * 20D));
    }

private int getCooldown(ItemStack stack) {
        return Math.max(0, stack.getOrDefault(RelicsDataComponents.CLOT_OF_TIME_COOLDOWN, 0));
    }

private void setCooldown(ItemStack stack, int cooldown) {
        var clamped = Math.max(0, cooldown);

        if (stack.getOrDefault(RelicsDataComponents.CLOT_OF_TIME_COOLDOWN, 0) != clamped)
            stack.set(RelicsDataComponents.CLOT_OF_TIME_COOLDOWN, clamped);
    }

private static void setRewindCursor(ItemStack stack, double cursor) {
        if (Double.compare(stack.getOrDefault(RelicsDataComponents.CLOT_OF_TIME_REWIND_CURSOR, -1D), cursor) != 0)
            stack.set(RelicsDataComponents.CLOT_OF_TIME_REWIND_CURSOR, cursor);
    }

private static void setPath(ItemStack stack, List<PathPointData> path) {
        if (!stack.getOrDefault(RelicsDataComponents.CLOT_OF_TIME_PATH, List.<PathPointData>of()).equals(path))
            stack.set(RelicsDataComponents.CLOT_OF_TIME_PATH, path);
    }

private static boolean shouldAppendPoint(Player player, PathPointData lastPoint, String currentDimension) {
        var lastDimension = lastPoint.dimension().isBlank() ? currentDimension : lastPoint.dimension();

        return !lastDimension.equals(currentDimension)
                || !player.blockPosition().equals(BlockPos.containing(lastPoint.x(), lastPoint.y(), lastPoint.z()));
    }

private static List<PathPointData> buildUpdatedPath(List<PathPointData> storedPath, int rememberedTicks, PathPointData newPoint) {
        var keepFrom = Math.max(0, storedPath.size() - (rememberedTicks - 1));
        var path = new ArrayList<PathPointData>(Math.min(rememberedTicks, storedPath.size() + 1));

        for (int index = keepFrom; index < storedPath.size(); index++)
            path.add(storedPath.get(index));

        path.add(newPoint);

        return path;
    }

public static PathPointData fromPlayer(Player player, String dimension) {
            return new PathPointData(player.getX(), player.getY(), player.getZ(), player.getYRot(), player.getXRot(), player.getHealth(), dimension);
        }

@SubscribeEvent
        public static void onRenderFrame(RenderFrameEvent.Pre event) {
            var minecraft = Minecraft.getInstance();
            var player = minecraft.player;

            if (player == null || minecraft.isPaused())
                return;

            if (!(player.isUsingItem() && player.getUseItem().getItem() instanceof ClotOfTimeItem item))
                return;

            if (player.getTicksUsingItem() <= 1)
                return;

            var stack = player.getUseItem();
            var path = stack.getOrDefault(RelicsDataComponents.CLOT_OF_TIME_PATH, List.<PathPointData>of());

            if (path.size() < 2)
                return;

            var lastIndex = path.size() - 1;
            double cursor = stack.getOrDefault(RelicsDataComponents.CLOT_OF_TIME_REWIND_CURSOR, -1D);

            if (cursor < 0D || cursor > lastIndex)
                cursor = lastIndex;

            var partial = Mth.clamp(RenderUtils.getPartialTick(false), 0F, 1F);
            var speed = 1.05D + Math.min(3D, Math.max(0, player.getTicksUsingItem() - 1) * 0.03D);

            cursor = Math.max(0D, cursor - speed * partial);

            var segment = Mth.floor(cursor);
            var t = (float) (cursor - segment);

            var p0 = path.get(Math.max(0, segment - 1));
            var p1 = path.get(segment);
            var p2 = path.get(Math.min(lastIndex, segment + 1));
            var p3 = path.get(Math.min(lastIndex, segment + 2));

            var currentDimension = player.level().dimension().location().toString();
            var p1Dimension = p1.dimension().isBlank() ? currentDimension : p1.dimension();
            var p2Dimension = p2.dimension().isBlank() ? currentDimension : p2.dimension();

            double x;
            double y;
            double z;

            float targetYRot;
            float targetXRot;

            if (!p1Dimension.equals(p2Dimension)) {
                var point = p1Dimension.equals(currentDimension) ? p1 : p2Dimension.equals(currentDimension) ? p2 : t <= 0.5F ? p1 : p2;

                x = point.x();
                y = point.y();
                z = point.z();

                targetYRot = point.yRot();
                targetXRot = point.xRot();
            } else {
                x = Mth.catmullrom(t, (float) p0.x(), (float) p1.x(), (float) p2.x(), (float) p3.x());
                y = Mth.catmullrom(t, (float) p0.y(), (float) p1.y(), (float) p2.y(), (float) p3.y());
                z = Mth.catmullrom(t, (float) p0.z(), (float) p1.z(), (float) p2.z(), (float) p3.z());

                var targetRotation = item.interpolateLookRotationCatmullrom(t, p0, p1, p2, p3);

                targetYRot = targetRotation.yRot();
                targetXRot = targetRotation.xRot();
            }

            var yRot = Mth.rotLerp(0.45F, player.getYRot(), targetYRot);
            var xRot = Mth.lerp(0.45F, player.getXRot(), Mth.clamp(targetXRot, -90F, 90F));

            player.setYRot(yRot);
            player.setXRot(xRot);
            player.setPos(x, y, z);
            player.setYHeadRot(yRot);
            player.setDeltaMovement(Vec3.ZERO);

            player.yRotO = yRot;
            player.xRotO = xRot;
            player.yBodyRot = yRot;
            player.yHeadRotO = yRot;
            player.yBodyRotO = yRot;
            player.fallDistance = 0F;
        }

public static <T> DeferredHolder<DataComponentType<?>, DataComponentType<T>> construct(String name, Codec<T> codec) {
        return DATA_COMPONENTS.register(name, () -> DataComponentType.<T>builder()
                .persistent(codec)
                .build());
    }

@Override
    public void tick() {
        super.tick();
        this.prevRaiseArmsAmount = raiseArmsAmount;
        this.prevLeftArmAmount = raiseLeftArmAmount;
        this.prevShootTongueAmount = shootTongueAmount;
        this.prevLastTongueDistance = lastTongueDistance;
        if (this.getAnimation() == ANIMATION_SMASH && raiseArmsAmount < 5F) {
            raiseArmsAmount++;
        }
        if (this.getAnimation() != ANIMATION_SMASH && raiseArmsAmount > 0F) {
            raiseArmsAmount--;
        }
        if (this.raisingLeftArm() && raiseLeftArmAmount < 5F) {
            raiseLeftArmAmount++;
        }
        if (!this.raisingLeftArm() && raiseLeftArmAmount > 0F) {
            raiseLeftArmAmount--;
        }
        if (this.getLickTicks() > 0 && shootTongueAmount < 10F) {
            shootTongueAmount++;
        }
        if (this.getLickTicks() <= 0 && shootTongueAmount > 0F) {
            shootTongueAmount--;
        }
        if (!level().isClientSide && this.hasBarrel()) {
            if (this.getAnimation() == ANIMATION_DRINK_BARREL && this.getAnimationTick() >= 60) {
                this.setHasBarrel(false);
                this.heal(10);
                this.addEffect(new MobEffectInstance(MobEffects.DAMAGE_BOOST, 400, 0));
                this.addEffect(new MobEffectInstance(MobEffects.DAMAGE_RESISTANCE, 400, 0));
                this.addEffect(new MobEffectInstance(MobEffects.REGENERATION, 400, 4));
            }
            if (this.getAnimation() == ANIMATION_THROW_BARREL && this.getAnimationTick() >= 15) {
                LivingEntity attackTarget = this.getTarget();
                if (attackTarget != null && attackTarget.isAlive()) {
                    this.setHasBarrel(false);
                    Vec3 hand = new Vec3(0.65F, -0.3F, 0.9F).xRot(-this.getXRot() * ((float) Math.PI / 180F)).yRot(-this.getYHeadRot() * ((float) Math.PI / 180F));
                    Vec3 handOnBody = this.getEyePosition().add(hand);
                    ThrownWasteDrumEntity wasteDrumEntity = ACEntityRegistry.THROWN_WASTE_DRUM.get().create(level());
                    wasteDrumEntity.setPos(handOnBody);
                    Vec3 toss = attackTarget.getEyePosition().subtract(handOnBody).multiply(0.35F, 0, 0.35F).add(0, 0.4, 0);
                    wasteDrumEntity.setYRot(-((float) Mth.atan2(toss.x, toss.z)) * 180.0F / (float) Math.PI);
                    level().addFreshEntity(wasteDrumEntity);
                    wasteDrumEntity.setDeltaMovement(toss.normalize().scale(attackTarget.distanceTo(this) * 0.2F));
                }
            }
        }
        Entity tongueTarget = this.getTongueTarget();
        if (level().isClientSide) {
            if (tongueTarget != null && tongueTarget.isAlive()) {
                lastTongueDistance = this.distanceTo(tongueTarget) - 0.5F;
            }
        } else {
            LivingEntity attackTarget = this.getTarget();
            if (this.getLickTicks() > 0) {
                this.setLickTicks(this.getLickTicks() - 1);
                if (attackTarget != null && attackTarget.isAlive() && this.hasLineOfSight(attackTarget) && attackTarget.distanceTo(this) < 20) {
                    this.setTongueTargetId(attackTarget.getId());
                    this.lookAt(EntityAnchorArgument.Anchor.EYES, attackTarget.getEyePosition());
                } else {
                    this.setTongueTargetId(-1);
                }
            } else {
                this.setTongueTargetId(-1);
            }
        }
        if (tongueTarget instanceof LivingEntity living) {
            if (this.shootTongueAmount >= 5F) {
                postAttackEffect(living);
                tongueTarget.hurt(damageSources().mobAttack(this), 4);
                living.knockback(0.3D, living.getX() - this.getX(), tongueTarget.getZ() - this.getZ());
                this.setLickTicks(0);
            }
        }
        AnimationHandler.INSTANCE.updateAnimations(this);
    }

protected void registerGoals() {
        this.goalSelector.addGoal(0, new FloatGoal(this));
        this.goalSelector.addGoal(1, new MeleeGoal());
        this.goalSelector.addGoal(2, new PickupBarrelGoal());
        this.goalSelector.addGoal(3, new RandomStrollGoal(this, 1.0D, 45));
        this.goalSelector.addGoal(3, new LookAtPlayerGoal(this, Player.class, 15.0F));
        this.goalSelector.addGoal(3, new RandomLookAroundGoal(this));
        this.targetSelector.addGoal(1, new HurtByTargetGoal(this));
        this.targetSelector.addGoal(2, new NearestAttackableTargetGoal<>(this, Player.class, true, false));
        this.targetSelector.addGoal(3, new NearestAttackableTargetGoal<>(this, AbstractVillager.class, true, false));
    }

public Entity getTongueTarget() {
        int id = this.entityData.get(TONGUE_TARGET_ID);
        return id == -1 ? null : level().getEntity(id);
    }

public void postAttackEffect(LivingEntity entity) {
        if (entity != null && entity.isAlive()) {
            entity.addEffect(new MobEffectInstance(ACEffectRegistry.IRRADIATED.get(), 400));
        }
    }

public void addAdditionalSaveData(CompoundTag compound) {
        super.addAdditionalSaveData(compound);
        compound.putBoolean("HasBarrel", this.hasBarrel());
    }

public void readAdditionalSaveData(CompoundTag compound) {
        super.readAdditionalSaveData(compound);
        this.setHasBarrel(compound.getBoolean("HasBarrel"));
    }

@Override
        public boolean canUse() {
            LivingEntity target = BrainiacEntity.this.getTarget();
            return target != null && target.isAlive();
        }

@Override
        public void tick() {
            LivingEntity target = BrainiacEntity.this.getTarget();
            if (tongueCooldown > 0) {
                tongueCooldown--;
            }
            if (target != null && target.isAlive()) {
                double dist = BrainiacEntity.this.distanceTo(target);
                if (BrainiacEntity.this.getAnimation() == NO_ANIMATION) {
                    if (BrainiacEntity.this.getHealth() < BrainiacEntity.this.getMaxHealth() * 0.5F && BrainiacEntity.this.hasBarrel() && BrainiacEntity.this.random.nextInt(20) == 0) {
                        BrainiacEntity.this.setAnimation(ANIMATION_DRINK_BARREL);
                    }
                    BrainiacEntity.this.getNavigation().moveTo(target, 1.2D);
                    if (BrainiacEntity.this.hasLineOfSight(target)) {
                        if (BrainiacEntity.this.getHealth() < BrainiacEntity.this.getMaxHealth() * 0.75F && dist < 20 && BrainiacEntity.this.hasBarrel() && BrainiacEntity.this.random.nextInt(30) == 0) {
                            BrainiacEntity.this.setAnimation(ANIMATION_THROW_BARREL);
                            BrainiacEntity.this.playSound(ACSoundRegistry.BRAINIAC_THROW.get());
                        }
                        if (dist < BrainiacEntity.this.getBbWidth() + target.getBbWidth() + 3.5D) {
                            BrainiacEntity.this.setAnimation(BrainiacEntity.this.random.nextBoolean() ? ANIMATION_SMASH : ANIMATION_BITE);
                            BrainiacEntity.this.playSound(ACSoundRegistry.BRAINIAC_ATTACK.get());
                            return;
                        }
                        if (tongueCooldown == 0 && BrainiacEntity.this.random.nextInt(16) == 0 && dist < 25) {
                            BrainiacEntity.this.playSound(ACSoundRegistry.BRAINIAC_LICK.get());
                            BrainiacEntity.this.setLickTicks(20);
                            tongueCooldown = 15 + BrainiacEntity.this.random.nextInt(15);
                        }
                    } else {
                        BrainiacEntity.this.setLickTicks(0);
                    }
                }
                if (BrainiacEntity.this.getAnimation() == ANIMATION_SMASH) {
                    if (BrainiacEntity.this.getAnimationTick() >= 10 && BrainiacEntity.this.getAnimationTick() <= 15) {
                        checkAndDealDamage(target, 2);
                    }
                }
                if (BrainiacEntity.this.getAnimation() == ANIMATION_BITE) {
                    if (BrainiacEntity.this.getAnimationTick() >= 10 && BrainiacEntity.this.getAnimationTick() <= 15) {
                        checkAndDealDamage(target, 1);
                    }
                }
            }
        }

@Override
        public void tick() {
            super.tick();
            if (blockPos != null) {
                BrainiacEntity.this.lookAt(EntityAnchorArgument.Anchor.EYES, Vec3.atCenterOf(blockPos));
                if (this.isReachedTarget()) {
                    BrainiacEntity.this.getNavigation().stop();
                    if (BrainiacEntity.this.getAnimation() == NO_ANIMATION) {
                        BrainiacEntity.this.setAnimation(ANIMATION_BITE);
                    }
                    if (BrainiacEntity.this.getAnimation() == ANIMATION_BITE && BrainiacEntity.this.getAnimationTick() >= 10 && BrainiacEntity.this.getAnimationTick() <= 15) {
                        if (isValidTarget(level(), blockPos)) {
                            level().destroyBlock(blockPos, false);
                            BrainiacEntity.this.setHasBarrel(true);
                        }
                    }
                }

            }
        }

@Override
        protected boolean isValidTarget(LevelReader worldIn, BlockPos pos) {
            return pos != null && worldIn.getBlockState(pos).is(ACBlockRegistry.WASTE_DRUM.get());
        }

public void tick() {
        if (!this.isNoGravity()) {
            this.setDeltaMovement(this.getDeltaMovement().add(0.0D, -0.08D, 0.0D));
        }
        this.move(MoverType.SELF, this.getDeltaMovement());
        this.setDeltaMovement(this.getDeltaMovement().scale(0.9D));
        if (this.onGround()) {
            this.setOnGroundFor(this.getOnGroundFor() + 1);
            this.setDeltaMovement(this.getDeltaMovement().multiply(0.7D, -0.7, 0.7D));
        }
        if (this.getDeltaMovement().length() > 0.03F) {
            AABB killBox = this.getBoundingBox();
            boolean b = false;
            for (LivingEntity entity : this.level().getEntitiesOfClass(LivingEntity.class, killBox)) {
                if (!(entity instanceof BrainiacEntity)) {
                    b = true;
                    entity.hurt(ACDamageTypes.causeAcidDamage(level().registryAccess()), 2);
                }
            }
            if (b) {
                this.setDeltaMovement(this.getDeltaMovement().multiply(0.2D, 1, 0.2D));
            }
        }
        if (this.getOnGroundFor() >= MAX_TIME && !level().isClientSide) {
            if (this.getOnGroundFor() == MAX_TIME) {
                BlockPos landed = this.blockPosition();
                while (landed.getY() < level().getMaxBuildHeight() && (!level().getBlockState(landed).isAir() || !level().getBlockState(landed).getFluidState().isEmpty() && level().getBlockState(landed).getFluidState().getFluidType() != ACFluidRegistry.ACID_FLUID_TYPE.get())) {
                    landed = landed.above();
                }
                removeWasteAt = landed;
                if (level().getBlockState(removeWasteAt).isAir()) {
                    BlockState fluid = ACBlockRegistry.ACID.get().defaultBlockState();
                    level().setBlockAndUpdate(removeWasteAt, fluid);
                }
            }
            if (this.getOnGroundFor() >= MAX_TIME + 15 && removeWasteAt != null) {
                this.remove(RemovalReason.DISCARDED);
                if (level().getFluidState(removeWasteAt).getFluidType() == ACFluidRegistry.ACID_FLUID_TYPE.get()) {
                    level().setBlockAndUpdate(removeWasteAt, Blocks.AIR.defaultBlockState());
                }
            }
        }
    }

